  sub: string;          // ユーザーID
  username: string;     // ユーザー名
  server: string;       // サーバーID
  iat: number;         // 発行時刻
  exp: number;         // 有効期限
}

// トークン生成
function generateTokens(user: User): {
  accessToken: string;
  refreshToken: string;
}
